          <Typography.Text type="secondary">
            {state.data.total} event{state.data.total === 1 ? '' : 's'}
            {state.data.truncated ? ' — more than shown here' : ''}
          </Typography.Text>
          <Flex gap={8}>
            <Button
              disabled={page === 0}
              onClick={() => {
                setPage((p) => Math.max(0, p - 1));
                reload();
              }}
            >
              Previous
            </Button>
            <Button
              disabled={!state.data.truncated}
              onClick={() => {
                setPage((p) => p + 1);
                reload();
              }}
            >
              Next
            </Button>
          </Flex>
        </Flex>
      )}
    </Section>
  );
}

